from collections import deque
import time

class TokenBucket:
    def __init__(self, capacity: float, refill_per_sec: float, clock=time.time):
        self.capacity = capacity
        self.refill_per_sec = refill_per_sec
        self.tokens = capacity
        self.clock = clock
        self.last_refill_time = clock()
        self.refill_queue = deque()

    def _refill(self):
        current_time = self.clock()
        if not self.refill_queue or current_time >= self.refill_queue[-1]:
            elapsed_time = max(current_time - self.last_refill_time, 0)
            tokens_to_add = min(elapsed_time * self.refill_per_sec, self.capacity - self.tokens)
            self.tokens = min(self.capacity, self.tokens + tokens_to_add)
            self.last_refill_time = current_time
            if tokens_to_add > 0:
                self.refill_queue.append(current_time + 1 / self.refill_per_sec)

    def allow(self, cost: float = 1) -> bool:
        self._refill()
        if self.tokens >= cost:
            self.tokens -= cost
            return True
        return False

    @property
    def tokens(self) -> float:
        self._refill()
        return self._tokens

    @tokens.setter
    def tokens(self, value: float):
        self._tokens = min(value, self.capacity)
