from typing import List, Tuple
import re

def top_customers(rows: List[dict], n: int) -> List[Tuple[str, float]]:
    def parse_amount(amount_str: str) -> float:
        amount_str = amount_str.strip()
        if not amount_str:
            return 0.0
        match = re.match(r'^-?\$?(\d+(,\d{3})*(\.\d+)?|\.\d+)$', amount_str.replace(',', ''))
        if not match:
            return 0.0
        return round(float(match.group(1).replace(',', '')), 2)

    customers = {}
    for row in rows:
        name = row.get('customer').strip().lower()
        if not name:
            continue
        amount = parse_amount(row.get('amount'))
        if amount == 0.0:
            continue
        if name not in customers:
            customers[name] = amount
        else:
            customers[name] += amount

    sorted_customers = sorted(customers.items(), key=lambda x: (-x[1], x[0]))
    return sorted_customers[:n]
